package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's pools: each a name, at most once on the sheet, and its members, each a person on the
 * sheet at most once per pool with a share percent (two decimals, above 0.00 and at most 100.00).
 * A pool's total adds up its members' shares, a retired member's (one with a retirement date set,
 * whatever the date) counting as 0.00; the pool is balanced when the total is exactly 100.00.
 * <p>
 * With a pot set on the sheet, each member of a balanced pool has a cut: the pot times their share
 * divided by 100, rounded half to even to two decimals, a retired member's 0.00. The remainder, the
 * pot less the cuts added up, goes to the member with the largest share (the earliest added on a
 * tie), so the cuts total exactly the pot. An unbalanced pool, or no pot, has no cuts.
 */
@Service
public class PoolService {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /**
     * A member as listed: the person's id and current name, their share, whether they are retired, and
     * their cut of the pot (two decimals; blank when the pool is unbalanced or there is no pot).
     */
    public record MemberView(long personId, String name, String share, boolean retired, String cut) {
    }

    /** A pool as listed: its members in the order they were added, their total share (two decimals) and balance. */
    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, SheetRepository sheetRows, Audit audit, RoleService roles) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
        this.roles = roles;
    }

    @Transactional(readOnly = true)
    public List<PoolView> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        if (all.isEmpty()) {
            return List.of();
        }
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PoolMember>> byPool = members
                .findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList()).stream()
                .collect(Collectors.groupingBy(PoolMember::getPoolId));
        BigDecimal pot = sheetRows.findById(sheetId).map(s -> s.getPot()).orElse(null);
        List<PoolView> out = new ArrayList<>();
        for (Pool pool : all) {
            out.add(view(pool, byPool.getOrDefault(pool.getId(), List.of()), byId, pot));
        }
        return out;
    }

    private static PoolView view(Pool pool, List<PoolMember> poolMembers, Map<Long, Person> byId, BigDecimal pot) {
        List<Person> listed = new ArrayList<>();
        List<BigDecimal> shares = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (PoolMember m : poolMembers) {
            Person p = byId.get(m.getPersonId());
            if (p == null) {
                continue;
            }
            BigDecimal share = m.getShare().setScale(2);
            listed.add(p);
            shares.add(share);
            if (!p.isRetired()) {
                total = total.add(share);
            }
        }
        boolean balanced = total.compareTo(HUNDRED) == 0;
        List<BigDecimal> cuts = balanced && pot != null ? cuts(pot, listed, shares) : null;
        List<MemberView> views = new ArrayList<>();
        for (int i = 0; i < listed.size(); i++) {
            Person p = listed.get(i);
            views.add(new MemberView(p.getId(), p.getName(), shares.get(i).toPlainString(), p.isRetired(),
                    cuts == null ? "" : cuts.get(i).toPlainString()));
        }
        return new PoolView(pool.getId(), pool.getName(), views, total.toPlainString(), balanced);
    }

    /**
     * Each member's cut of the pot, in the members' order: the pot times their share over 100, half to
     * even, a retired member's 0.00; the remainder to the live member with the largest share, the
     * earliest on a tie.
     */
    private static List<BigDecimal> cuts(BigDecimal pot, List<Person> listed, List<BigDecimal> shares) {
        List<BigDecimal> cuts = new ArrayList<>();
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int largest = -1;
        for (int i = 0; i < listed.size(); i++) {
            BigDecimal cut = BigDecimal.ZERO.setScale(2);
            if (!listed.get(i).isRetired()) {
                cut = pot.multiply(shares.get(i)).divide(HUNDRED, 2, RoundingMode.HALF_EVEN);
                if (largest < 0 || shares.get(i).compareTo(shares.get(largest)) > 0) {
                    largest = i;
                }
            }
            cuts.add(cut);
            sum = sum.add(cut);
        }
        if (largest >= 0) {
            cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)));
        }
        return cuts;
    }

    /** Add a pool (trimmed); a blank name is refused (422), one already on the sheet (409). */
    @Transactional
    public void add(String sheetId, String user, String name) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        String text = name == null ? "" : name.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Enter a pool name.");
        }
        // hold the sheet so the same name added twice at the same moment is checked one after the other
        sheetRows.findLockedById(sheetId);
        if (pools.existsBySheetIdAndName(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet.");
        }
        try {
            pools.saveAndFlush(new Pool(sheetId, text));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet.");
        }
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + text);
    }

    /**
     * Add a person to a pool with a share: refused (422) for a share that is not a number of at most
     * two decimals above 0.00 and at most 100.00, (409) for a person already in the pool.
     */
    @Transactional
    public void addMember(String sheetId, String user, long poolId, long personId, String share) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        BigDecimal pct = share(share);
        sheetRows.findLockedById(sheetId);
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Choose a person."));
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
        }
        try {
            members.saveAndFlush(new PoolMember(pool.getId(), person.getId(), pct));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool.");
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + pct.toPlainString());
    }

    private static BigDecimal share(String text) {
        String s = text == null ? "" : text.trim();
        if (!s.matches("\\d{1,3}(\\.\\d{1,2})?")) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "Enter a share of at most two decimals.");
        }
        BigDecimal pct = new BigDecimal(s).setScale(2);
        if (pct.signum() <= 0 || pct.compareTo(HUNDRED) > 0) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "A share is more than 0.00 and at most 100.00.");
        }
        return pct;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, output, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The sheet's pools: each a name (trimmed, at most once on the sheet) and its members, each a
// person chosen from the sheet at most once per pool, with a share percent (two decimals, above
// 0.00 and at most 100.00). A person may be in several pools. Each pool shows its total share,
// a retired member's (one with a retirement date set, whatever the date) counting as 0.00, and
// whether it is balanced: the total exactly 100.00. With a pot set, each member of a balanced pool
// shows their cut of it (worked out by the store; blank when unbalanced or no pot). Re-read from
// the store on every sheet load and whenever the people or the pot change.
export interface PoolMember {
  personId: number;
  name: string;
  share: string;
  retired: boolean;
  /** Their cut of the pot, two decimals; blank when the pool is unbalanced or there is no pot. */
  cut: string;
}

export interface Pool {
  id: number;
  name: string;
  members: PoolMember[];
  totalShare: string;
  balanced: boolean;
}

/** A person who may be chosen as a member. */
export interface PoolPerson {
  id: number;
  name: string;
}

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

function refusal(e: unknown, what: string): string {
  if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string' && e.status !== 403 && e.status < 500) {
    return e.error.message;
  }
  return e instanceof HttpErrorResponse && e.status === 403 ? 'Your role may not change pools.' : what;
}

@Component({
  selector: 'app-pool-row',
  template: `
    <article [attr.data-testid]="'pool-row-' + pool().name">
      <h3>{{ pool().name }}</h3>
      <p>
        Total share <strong data-testid="pool-total-share">{{ pool().totalShare }}</strong>
        Balanced <strong data-testid="pool-balanced">{{ pool().balanced ? 'yes' : 'no' }}</strong>
      </p>
      <ul [attr.aria-label]="'Members of ' + pool().name">
        @for (m of pool().members; track m.personId) {
          <li [attr.data-testid]="'pool-member-' + pool().name + '-' + m.personId">
            {{ m.name }}@if (m.retired) { (retired)}:
            <span data-testid="pool-share">{{ m.share }}</span>
            cut <span data-testid="pool-cut">{{ m.cut }}</span>
          </li>
        }
      </ul>
      <form [attr.aria-label]="'Add a member to ' + pool().name" (submit)="add($event)">
        <label [for]="'pool-member-select-' + pool().id">Person</label>
        <select
          [id]="'pool-member-select-' + pool().id"
          data-testid="pool-member-select"
          [value]="personInput()"
          (change)="personInput.set($any($event.target).value); error.set(null)"
        >
          <option value="">Choose a person</option>
          @for (p of people(); track p.id) {
            <option [value]="'' + p.id" [selected]="personInput() === '' + p.id">{{ p.name }}</option>
          }
        </select>
        <label [for]="'pool-member-share-' + pool().id">Share %</label>
        <input
          [id]="'pool-member-share-' + pool().id"
          data-testid="pool-member-share"
          inputmode="decimal"
          [value]="shareInput()"
          (input)="shareInput.set($any($event.target).value); error.set(null)"
        />
        <button type="submit" data-testid="pool-member-add">Add member</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-error">{{ err }}</p>
        }
      </form>
    </article>
  `,
})
export class PoolRow {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly pool = input.required<Pool>();
  readonly people = input.required<PoolPerson[]>();
  /** The sheet's pools as the store holds them once a member was added. */
  readonly changed = output<Pool[]>();

  protected readonly personInput = signal('');
  protected readonly shareInput = signal('');
  protected readonly error = signal<string | null>(null);
  private submitting = false;

  protected async add(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const personId = Number(this.personInput());
    const share = this.shareInput().trim();
    if (!personId) {
      this.error.set('Choose a person.');
      return;
    }
    if (this.pool().members.some((m) => m.personId === personId)) {
      this.error.set('That person is already in the pool.');
      return;
    }
    if (!SHARE.test(share)) {
      this.error.set('Enter a share of at most two decimals.');
      return;
    }
    const pct = Number(share);
    if (pct <= 0 || pct > 100) {
      this.error.set('A share is more than 0.00 and at most 100.00.');
      return;
    }
    const sheet = this.session.sheet();
    this.submitting = true;
    try {
      const pools = await firstValueFrom(
        this.http.post<Pool[]>('/api/pools/members/add', {
          sheet,
          user: this.session.user(),
          pool: this.pool().id,
          person: personId,
          share,
        }),
      );
      if (this.session.sheet() !== sheet) return;
      this.personInput.set('');
      this.shareInput.set('');
      this.changed.emit(pools);
    } catch (e) {
      if (this.session.sheet() === sheet) this.error.set(refusal(e, 'Could not add this member.'));
    } finally {
      this.submitting = false;
    }
  }
}

@Component({
  selector: 'app-pools',
  imports: [PoolRow],
  template: `
    <section aria-labelledby="pools-heading">
      <h2 id="pools-heading">Pools</h2>
      <form aria-label="Pool" (submit)="add($event)">
        <label for="pool-form-name">Name</label>
        <input
          id="pool-form-name"
          data-testid="pool-form-name"
          [value]="nameInput()"
          (input)="nameInput.set($any($event.target).value); error.set(null)"
        />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error() ?? loadError(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
      @for (p of pools(); track p.id) {
        <app-pool-row [pool]="p" [people]="people()" (changed)="changed($event)" />
      }
    </section>
  `,
})
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Everyone on the sheet, retired or not: the people a member is chosen from. */
  readonly people = input.required<PoolPerson[]>();
  /** The sheet's pot, blank for none: a change re-reads the cuts. */
  readonly pot = input('');

  protected readonly pools = signal<Pool[]>([]);
  protected readonly nameInput = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly loadError = signal<string | null>(null);
  private submitting = false;
  /** Bumped by every read, so only the latest one's answer is shown. */
  private reads = 0;

  constructor() {
    effect(() => {
      this.session.sheet();
      this.session.loads();
      this.pools.set([]);
      this.nameInput.set('');
      this.error.set(null);
    });
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.people(); // a person retired, renamed or added: re-read the totals and names
      this.pot(); // the pot changed: re-read the cuts
      if (sheet) void this.fetch(sheet);
    });
  }

  private async fetch(sheet: string): Promise<void> {
    const read = ++this.reads;
    try {
      const pools = await firstValueFrom(this.http.post<Pool[]>('/api/pools/list', { sheet }));
      if (read === this.reads && this.session.sheet() === sheet) {
        this.pools.set(pools);
        this.loadError.set(null);
      }
    } catch {
      if (read === this.reads) this.loadError.set('Could not read the pools on this sheet.');
    }
  }

  protected changed(pools: Pool[]): void {
    ++this.reads;
    this.pools.set(pools);
  }

  protected async add(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const name = this.nameInput().trim();
    if (!name) {
      this.error.set('Enter a pool name.');
      return;
    }
    if (this.pools().some((p) => p.name === name)) {
      this.error.set('That pool is already on the sheet.');
      return;
    }
    const sheet = this.session.sheet();
    this.submitting = true;
    try {
      const pools = await firstValueFrom(
        this.http.post<Pool[]>('/api/pools/add', { sheet, user: this.session.user(), name }),
      );
      if (this.session.sheet() !== sheet) return;
      ++this.reads;
      this.pools.set(pools);
      this.nameInput.set('');
    } catch (e) {
      if (this.session.sheet() === sheet) this.error.set(refusal(e, 'Could not add this pool.'));
    } finally {
      this.submitting = false;
    }
  }
}

